#!/usr/bin/env node
// Generates phase1/src/generated/errorIds.ts from docs/errors/registry.json.
// Usage: node scripts/errors/gen-registry.mjs [--check]   (run from phase1/)
// --check fails when the generated file on disk is out of date.
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname,resolve} from 'node:path';
const here=dirname(fileURLToPath(import.meta.url));
const registryPath=resolve(here,'../../../docs/errors/registry.json');
const outPath=resolve(here,'../../src/generated/errorIds.ts');
const ID_RE=/^SOM-[A-Z]{2,4}-\d{3}$/;
const SEVERITIES=['debug','info','warn','error'];
const reg=JSON.parse(readFileSync(registryPath,'utf8'));
const seen=new Set();
for(const e of reg.entries){
  if(!ID_RE.test(e.id))throw new Error(`bad id ${e.id}`);
  if(seen.has(e.id))throw new Error(`duplicate id ${e.id}`);
  seen.add(e.id);
  if(!SEVERITIES.includes(e.default_severity))throw new Error(`${e.id}: bad severity`);
  if(e.status==='active'&&!e.user_message_key)throw new Error(`${e.id}: active entry needs user_message_key`);
}
const active=reg.entries.filter(e=>e.status==='active');
const retired=reg.entries.filter(e=>e.status!=='active');
const constName=id=>id.replace(/^SOM-/,'').replace(/-/g,'_');
const q=s=>JSON.stringify(s);
const lines=[];
lines.push('// GENERATED by scripts/errors/gen-registry.mjs from docs/errors/registry.json. Do not edit by hand.');
lines.push('');
lines.push('/** Active error codes. Key is the constant name, value is the SOM code. */');
lines.push('export const ERROR_IDS = {');
for(const e of active)lines.push(`  ${constName(e.id)}: ${q(e.id)},`);
lines.push('} as const;');
lines.push('');
lines.push('/** Value union of all active SOM codes. */');
lines.push('export type ErrorId = typeof ERROR_IDS[keyof typeof ERROR_IDS];');
lines.push('');
lines.push("export type ErrorSeverity = 'debug' | 'info' | 'warn' | 'error';");
lines.push('export interface ErrorMeta {');
lines.push('  slug: string;');
lines.push('  domain: string;');
lines.push('  category: string;');
lines.push('  severity: ErrorSeverity;');
lines.push('  /** Registry permission flag: the event MAY be fatal. Per-event fatal is set only through logEvent({fatal:true}). */');
lines.push('  fatal: boolean;');
lines.push('  /** Default for "expected" (user-caused or policy outcome). An emission may override it. */');
lines.push('  expected: boolean;');
lines.push('  /** Registry metadata only. It never enables a retry button by itself. */');
lines.push('  recoverable: boolean;');
lines.push('  messageKey: string;');
lines.push('}');
lines.push('');
lines.push('export const ERROR_META: Record<ErrorId, ErrorMeta> = {');
for(const e of active){
  lines.push(`  ${q(e.id)}: {slug: ${q(e.slug)}, domain: ${q(e.domain)}, category: ${q(e.category)}, severity: ${q(e.default_severity)}, fatal: ${!!e.fatal}, expected: ${!!e.expected}, recoverable: ${!!e.recoverable}, messageKey: ${q(e.user_message_key)}},`);
}
lines.push('};');
lines.push('');
lines.push('/** Codes that exist in the registry but are not emittable (reserved, ci-only, deprecated). */');
lines.push('export const RETIRED_ERROR_IDS = [');
for(const e of retired)lines.push(`  ${q(e.id)}, // ${e.status}`);
lines.push('] as const;');
lines.push('');
const out=lines.join('\n');
if(process.argv.includes('--check')){
  if(!existsSync(outPath)||readFileSync(outPath,'utf8')!==out){console.error('errorIds.ts is out of date, run gen-registry.mjs');process.exit(1);}
  console.log(`ok: ${active.length} active, ${retired.length} retired`);
}else{
  writeFileSync(outPath,out);
  console.log(`wrote ${outPath}: ${active.length} active, ${retired.length} retired`);
}
